/* AP United States History, Period 3: 1754-1800 (Unit 3). Original teaching and practice aligned to the topics of the
   College Board's AP United States History Course and Exam Description: 3.1 Contextualizing Period 3, 3.2 The Seven Years' War
   (the French and Indian War), 3.3 Taxation Without Representation, 3.4 Philosophical Foundations of the American Revolution,
   3.5 The American Revolution, 3.6 The Influence of Revolutionary Ideals, 3.7 The Articles of Confederation, 3.8 The
   Constitutional Convention and Debates over Ratification, 3.9 The Constitution, 3.10 Shaping a New Republic, 3.11 Developing
   an American Identity, 3.12 Movement in the Early Republic, 3.13 Continuity and Change in Period 3. Maps are schematic
   sketches, never borders or areas; the timelines place events by their actual years. Dates and facts are standard textbook
   history, hedged where scholars differ (motives, casualty counts, how far ideals reached). No source is quoted: documents and
   pamphlets are named and paraphrased, and sources marked fictional are teaching constructions. Pending PixelLab art is listed
   in ART_REQUESTS.md; the pictures here are code-drawn meanwhile. */
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const board=(title,lines)=>({t:'board',title,lines});
const table=(title,head,col,rows)=>({t:'setups',title,head,cols:[col],rows});
const flow=(title,labels,details)=>{const pts={},polys=[],segs=[],notes=[];labels.forEach((label,i)=>{const x=i*36;for(const [j,xy] of [[0,[x,15]],[1,[x+28,15]],[2,[x+28,27]],[3,[x,27]]])pts['ABCD'[j]+i]=xy;polys.push({v:`A${i}B${i}C${i}D${i}`,label,col:i});notes.push({at:[x+14,7],text:details[i]});if(i<labels.length-1){pts['P'+i]=[x+29,21];pts['Q'+i]=[x+35,21];segs.push({v:`P${i}Q${i}`,arrows:1,col:i});}});return {t:'figure',title,view:[-3,103,0,34],pts,polys,segs,notes,dots:'',hide:Object.keys(pts).join('')};};
/* a scaled timeline: the x axis is calendar years and labels alternate above and below the line */
const years=(title,span,events)=>{const k=(span[1]-span[0])/170,pts={A:[span[0]+4*k,0],B:[span[1]-4*k,0]},notes=[];events.forEach(([y,text],i)=>{pts['E'+i]=[y,0];notes.push({at:[y,(i%2?-4.5:4.5)*k],text});});return {t:'figure',title,view:[span[0],span[1],-9*k,9*k],pts,hide:Object.keys(pts).join(''),dots:events.map((e,i)=>'E'+i).join(''),segs:[{v:'AB',arrows:1}],notes};};
/* regions as labelled boxes: schematic locations only, never borders */
const regions=(title,boxes)=>{const pts={},polys=[],notes=[];boxes.forEach(([label,x0,y0,x1,y1,detail],i)=>{[[x0,y0],[x1,y0],[x1,y1],[x0,y1]].forEach((xy,j)=>{pts['ABCD'[j]+i]=xy;});polys.push({v:`A${i}B${i}C${i}D${i}`,label,col:i});notes.push({at:[(x0+x1)/2,y0+2.4],text:detail});});return {t:'figure',title,view:[0,100,0,34],pts,polys,notes,dots:'',hide:Object.keys(pts).join('')};};
const timeline=years('Period 3 in real years: 1754 to 1800',[1745,1808],[[1754,'1754: War begins'],[1763,'1763: Treaty of Paris'],[1776,'1776: Declaration'],[1783,'1783: Peace'],[1789,'1789: Washington'],[1800,'1800: Election']]);
const taxes=years('Taxes and protest, to scale',[1762,1777],[[1765,'1765: Stamp Act'],[1770,'1770: Boston Massacre'],[1773,'1773: Tea Party'],[1774,'1774: Coercive Acts']]);
const warYears=years('The Revolutionary War, to scale',[1773,1785],[[1775,'1775: Lexington'],[1777,'1777: Saratoga'],[1781,'1781: Yorktown'],[1783,'1783: Treaty of Paris']]);
const nation=years('Building the republic, to scale',[1787,1802],[[1789,'1789: Washington'],[1794,'1794: Whiskey Rebellion'],[1798,'1798: Sedition Act'],[1800,'1800: Election']]);
const LINE=regions('Western land after 1763: a schematic, not a map',[['Colonial settlements',1,2,31,30,'Atlantic side'],['Proclamation line',33,2,65,30,'1763, schematic'],['Native homelands',67,2,98,30,'beyond the line']]);
